styleBlocks.css:
body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
}

.goals-severity-badge {
  font-size: 11px; font-weight: 700; padding: 2px 10px; border-radius: 4px;
  white-space: nowrap; flex-shrink: 0; text-transform: uppercase; letter-spacing: 0.3px;
}

.cycle-section {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
  margin-bottom: 0;
}

.cycle-widget-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
}

.cycle-widget-title-wrap {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.cycle-widget-kicker {
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.cycle-widget-title {
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0;
}

.cycle-widget-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.cycle-icon-btn,
.cycle-action-btn {
  min-width: 36px;
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  transition: background 0.15s, border-color 0.15s, color 0.15s, transform 0.05s;
}

.cycle-icon-btn:hover,
.cycle-action-btn:hover {
  background: var(--bg-hover);
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
  color: var(--text-primary);
}

.cycle-section svg {
  display: block;
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.cycle-prompt,
.cycle-summary-card {
  width: 100%;
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 82%, transparent);
  color: var(--text-primary);
  cursor: pointer;
  font: inherit;
  text-align: left;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}

.cycle-prompt:hover,
.cycle-summary-card:hover {
  background: var(--bg-hover);
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
}

.cycle-prompt-icon,
.cycle-summary-icon,
.cycle-draw-icon,
.cycle-alert-icon {
  flex: 0 0 auto;
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--accent);
}

.cycle-prompt-copy strong,
.cycle-summary-copy strong,
.cycle-draw-copy strong,
.cycle-alert strong {
  color: var(--text-primary);
  font-size: 13px;
  line-height: 1.35;
}

.cycle-prompt-copy span,
.cycle-summary-label,
.cycle-draw-copy span,
.cycle-draw-copy small,
.cycle-alert-detail {
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.45;
}

.cycle-meta-tag,
.cycle-draw-tag,
.cycle-period-entry,
.period-symptom-tag {
  max-width: 100%;
  border: 1px solid var(--border);
  background: var(--bg-card);
  color: var(--text-secondary);
}

.cycle-meta-tag,
.period-symptom-tag {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  min-height: 22px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  line-height: 1.25;
}

.cycle-draw-date {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px;
  background: var(--ref-band);
  border: 1px solid var(--ref-border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
}

.cycle-draw-phases,
.cycle-period-log {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  min-width: 0;
}

.cycle-draw-tag {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
  padding: 5px 10px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.cycle-phase-badge {
  display: inline-flex;
  align-items: center;
  min-height: 20px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  text-transform: capitalize;
  border: 1px solid transparent;
}

.cycle-period-entry {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  min-width: 0;
  padding: 5px 8px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.cycle-period-note {
  min-width: 0;
  color: var(--text-muted);
  font-style: italic;
  overflow-wrap: anywhere;
}

.cycle-alert {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid;
  border-left-width: 3px;
  border-radius: var(--radius-sm);
}

